//! Engine WASM ABI v1: what a package's `engine.wasm` exports and imports
//! (generated by [`export_engine!`](crate::export_engine)), and what the
//! host (`common::engine`) calls. Everything is plain WebAssembly numbers:
//! `i32` for pointers, lengths and results, `i64` for times.
//!
//! The module is `wasm32-unknown-unknown`, no WASI, built with 1-byte
//! memory pages and exactly the linear memory it needs (stack, data and
//! statics; it never grows). It must export its memory as `memory`.
//!
//! Exports:
//!
//! | export | signature | |
//! |---|---|---|
//! | `init` | `() -> i64` | called once after instantiation: makes the engine (its `Default`) and returns its I/O buffer, `ptr << 32 \| capacity` ([`io_buffer`]) |
//! | `on_location` | `(ptr: i32, len: i32) -> i32` | a GPS update: a postcard [`Location`](crate::Location) the host wrote at `ptr` |
//! | `on_timer` | `(now: i64) -> i32` | the timer `next_timer` asked for is due; `now` is the time it was due at |
//! | `on_event` | `(ptr: i32, len: i32) -> i32` | a client event: the engine's `Event` as postcard at `ptr` (it reads the time with `now()`) |
//! | `view` | `(out_ptr: i32, cap: i32) -> i32` | writes the engine's `View` as postcard to `out_ptr`; its length |
//! | `next_timer` | `() -> i64` | when the engine next wants `on_timer`, device time (unsigned); [`NO_TIMER`] (-1) for never |
//!
//! `on_*` return [`CHANGED`] (the view changed: clients must be told),
//! [`UNCHANGED`], or [`REFUSED`] (the input is not exactly one value of its
//! type; the engine is untouched). `view` returns [`REFUSED`] if the view
//! does not fit `cap`. The host passes inputs in the I/O buffer and has
//! `view` write there too. A trap is a bug in the package: the host drops
//! the engine.
//!
//! Imports, module `env`:
//!
//! | import | signature | |
//! |---|---|---|
//! | `now` | `() -> i64` | the device's clock, epoch ms (uptime until the GPS has given it the time) |
//! | `log` | `(ptr: i32, len: i32)` | a line (UTF-8) for the device's log |

/// The ABI version a package's manifest names (`Manifest::abi`).
pub const VERSION: u16 = 1;

/// `on_*`: the view changed.
pub const CHANGED: i32 = 1;
/// `on_*`: nothing for clients.
pub const UNCHANGED: i32 = 0;
/// `on_*`, `view`: not one value of the expected type, or no room.
pub const REFUSED: i32 = -1;

/// `next_timer`: no timer wanted. `u64::MAX` (as the i64 -1) rather than 0,
/// which is a real time (a start clamped to the epoch fires at once); a
/// timer at `u64::MAX` would never fire anyway.
pub const NO_TIMER: u64 = u64::MAX;

/// The I/O buffer [`export_engine!`](crate::export_engine) gives its
/// module: room for the largest `Location`, event or view.
pub const IO_CAP: usize = 256;

/// `init`'s result from the I/O buffer's address and capacity.
pub const fn io_buffer(ptr: u32, cap: u32) -> u64 {
    (ptr as u64) << 32 | cap as u64
}

/// The I/O buffer's (address, capacity) from `init`'s result.
pub const fn split_io_buffer(init: u64) -> (u32, u32) {
    ((init >> 32) as u32, init as u32)
}

/// Export and import names, NUL-terminated for wasm3.
pub mod names {
    use core::ffi::CStr;
    pub const INIT: &CStr = c"init";
    pub const ON_LOCATION: &CStr = c"on_location";
    pub const ON_TIMER: &CStr = c"on_timer";
    pub const ON_EVENT: &CStr = c"on_event";
    pub const VIEW: &CStr = c"view";
    pub const NEXT_TIMER: &CStr = c"next_timer";
    pub const MODULE: &CStr = c"env";
    pub const NOW: &CStr = c"now";
    pub const LOG: &CStr = c"log";
}
